import { deleteConfig } from "@/api/cmdb/ciConfig";

export default {
  props: ['isShow', "configId"],
  data() {
    return{
      description: '',
      saveLoading: false
    }
  },
  mounted() {},
  methods: {
    // 删除并提交
    delConfig(val) {
      let form = {
        id: this.configId,
        description: this.description,
        needCommit: val
      }
      this.saveLoading = true
      deleteConfig(form).then(res => {
        this.$message({
          type: 'success',
          message: '保存成功！'
        });
        this.saveLoading = false
        this.$emit('submitDelConfig')
      }).catch(() => {
        this.saveLoading = false
      })
    },

  }
}
